</head>
<body>
    <header>
        <h1>⚔️ WastedToken Mint ⚔️</h1>
        <p class="tagline">Forging memories in metal, one challenge at a time.</p>
    </header>

    <section class="hero">
        <canvas id="coin-hero"></canvas>
    </section>

    <section class="about">
        <h2>About the Mint</h2>
        <p>
            Founded in 2024, WastedToken Mint specializes in crafting exceptional challenge coins 
            that commemorate achievements, milestones, and camaraderie. Each coin is minted with 
            precision, combining traditional metalworking with modern design, ensuring that every 
            piece tells a unique story.
        </p>
        <p>
            Our coins are more than currency—they're badges of honor, collectible treasures, and 
            tokens of fellowship. Whether you're marking a personal victory, honoring a team, or 
            building a collection, our challenge coins deliver the weight, finish, and detail that 
            collectors demand.
        </p>
        <p>
            Each edition is limited. Each surface is refined. Every coin is a statement.
        </p>
    </section>

    <section class="editions">
        <h2>Coin Editions</h2>
        <div class="grid">
            <div class="edition" data-edition="bronze" data-state="available">
                <canvas class="edition-canvas"></canvas>
                <div class="edition-info">
                    <div class="edition-name">Bronze Edition</div>
                    <div class="edition-state">Available Now</div>
                    <button class="buy">Add to cart</button>
                </div>
            </div>

            <div class="edition" data-edition="silver" data-state="available">
                <canvas class="edition-canvas"></canvas>
                <div class="edition-info">
                    <div class="edition-name">Silver Edition</div>
                    <div class="edition-state">Available Now</div>
                    <button class="buy">Add to cart</button>
                </div>
            </div>

            <div class="edition" data-edition="gold" data-state="sold-out">
                <canvas class="edition-canvas"></canvas>
                <div class="edition-info">
                    <div class="edition-name">Gold Edition</div>
                    <div class="edition-state">SOLD OUT</div>
                </div>
            </div>

            <div class="edition" data-edition="black" data-state="coming-soon">
                <canvas class="edition-canvas"></canvas>
                <div class="edition-info">
                    <div class="edition-name">Black Obsidian</div>
                    <div class="edition-state">Minting Winter 2026</div>
                </div>
            </div>
        </div>
    </section>

    <footer>
        <p>&copy; 2024-2026 WastedToken Mint. Forged with honor.</p>
    </footer>

    <script>
        // 3D vector math
        class Vec3 {
            constructor(x=0, y=0, z=0) {
                this.x = x; this.y = y; this.z = z;
            }
            rotateX(a) {
                const c = Math.cos(a), s = Math.sin(a);
                return new Vec3(this.x, this.y*c - this.z*s, this.y*s + this.z*c);
            }
            rotateY(a) {
                const c = Math.cos(a), s = Math.sin(a);
                return new Vec3(this.x*c + this.z*s, this.y, -this.x*s + this.z*c);
            }
            project(fov=500) {
                const scale = fov / (this.z + fov);
                return {x: this.x*scale, y: this.y*scale, z: this.z, scale};
            }
        }

        // Coin mesh geometry
        class CoinMesh {
            constructor() {
                this.vertices = [];
                this.faces = [];
                this.createGeometry();
            }
            createGeometry() {
                const rad = 100, thick = 8, segs = 50;

                // Front face disc
                for (let i = 0; i <= segs; i++) {
                    for (let j = 0; j <= segs; j++) {
                        const r = (i / segs) * rad;
                        const a = (j / segs) * Math.PI * 2;
                        this.vertices.push(new Vec3(
                            Math.cos(a) * r, Math.sin(a) * r, thick/2
                        ));
                    }
                }

                const front = 0, back = (segs+1)*(segs+1);

                // Back face disc
                for (let i = 0; i <= segs; i++) {
                    for (let j = 0; j <= segs; j++) {
                        const r = (i / segs) * rad;
                        const a = (j / segs) * Math.PI * 2;
                        this.vertices.push(new Vec3(
                            Math.cos(a) * r, Math.sin(a) * r, -thick/2
                        ));
                    }
                }

                const stride = segs + 1;

                // Front face triangles
                for (let i = 0; i < segs; i++) {
                    for (let j = 0; j < segs; j++) {
                        const a = front + i*stride + j;
                        const b = front + i*stride + j+1;
                        const c = front + (i+1)*stride + j;
                        const d = front + (i+1)*stride + j+1;
                        this.faces.push([a,b,c, 1]); // 1 = front face
                        this.faces.push([b,d,c, 1]);
                    }
                }

                // Back face triangles
                for (let i = 0; i < segs; i++) {
                    for (let j = 0; j < segs; j++) {
                        const a = back + i*stride + j;
                        const b = back + i*stride + j+1;
                        const c = back + (i+1)*stride + j;
                        const d = back + (i+1)*stride + j+1;
                        this.faces.push([c,b,a, -1]); // -1 = back face
                        this.faces.push([c,d,b, -1]);
                    }
                }

                // Edge strip (reeded edge)
                for (let j = 0; j < segs; j++) {
                    const fa = front + j;
                    const fb = front + j+1;
                    const ba = back + j;
                    const bb = back + j+1;
                    this.faces.push([fa,ba,fb, 0]); // 0 = edge
                    this.faces.push([fb,ba,bb, 0]);
                }
            }
            getNormal(v0, v1, v2) {
                const e1 = {x: v1.x-v0.x, y: v1.y-v0.y, z: v1.z-v0.z};
                const e2 = {x: v2.x-v0.x, y: v2.y-v0.y, z: v2.z-v0.z};
                const nx = e1.y*e2.z - e1.z*e2.y;
                const ny = e1.z*e2.x - e1.x*e2.z;
                const nz = e1.x*e2.y - e1.y*e2.x;
                const len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
                return {x: nx/len, y: ny/len, z: nz/len};
            }
        }

        // Main coin renderer
        class CoinRenderer {
            constructor(canvas) {
                this.canvas = canvas;
                this.ctx = canvas.getContext('2d');
                this.width = canvas.width;
                this.height = canvas.height;
                this.mesh = new CoinMesh();
                this.animating = true;
                this.cx = this.width / 2;
                this.cy = this.height / 2;
            }

            render(t) {
                // Clear with gradient background
                this.ctx.fillStyle = '#0a0f1f';
                this.ctx.fillRect(0, 0, this.width, this.height);

                const bgGrad = this.ctx.createRadialGradient(this.cx, this.cy, 0, this.cx, this.cy, 250);
                bgGrad.addColorStop(0, 'rgba(70, 130, 180, 0.08)');
                bgGrad.addColorStop(1, 'rgba(10, 15, 31, 0)');
                this.ctx.fillStyle = bgGrad;
                this.ctx.fillRect(0, 0, this.width, this.height);

                const spinAngle = t * Math.PI * 2;
                const flipAngle = Math.sin(t * Math.PI) * Math.PI * 0.5;

                // Transform vertices
                const transformed = this.mesh.vertices.map(v => 
                    v.rotateX(flipAngle).rotateY(spinAngle)
                );

                // Project to 2D
                const projected = transformed.map(v => v.project(600));

                // Prepare face data with normals and depths
                const faceData = this.mesh.faces.map((face, idx) => {
                    const v0 = transformed[face[0]];
                    const v1 = transformed[face[1]];
                    const v2 = transformed[face[2]];
                    const faceType = face[3];

                    const normal = this.mesh.getNormal(v0, v1, v2);
                    const facing = normal.z > 0;
                    const light = facing ? Math.max(0.2, normal.z * 0.8 + 0.2) : 0;
                    const avgZ = (v0.z + v1.z + v2.z) / 3;

                    return {indices: face.slice(0,3), faceType, normal, facing, light, avgZ};
                });

                // Sort by depth for painter's algorithm
                faceData.sort((a, b) => a.avgZ - b.avgZ);

                // Render faces
                faceData.forEach(face => {
                    if (!face.facing) return;

                    const p0 = projected[face.indices[0]];
                    const p1 = projected[face.indices[1]];
                    const p2 = projected[face.indices[2]];

                    let color;
                    if (face.faceType === 1) {
                        // Front face: gold
                        const br = 0.5 + face.light * 0.5;
                        color = `rgb(${Math.round(212*br)},${Math.round(175*br)},${Math.round(55*br)})`;
                    } else if (face.faceType === -1) {
                        // Back face: darker gold
                        const br = 0.35 + face.light * 0.5;
                        color = `rgb(${Math.round(192*br)},${Math.round(160*br)},${Math.round(40*br)})`;
                    } else {
                        // Edge: bronze
                        const br = 0.3 + face.light * 0.4;
                        color = `rgb(${Math.round(120*br)},${Math.round(100*br)},${Math.round(60*br)})`;
                    }

                    this.ctx.fillStyle = color;
                    this.ctx.beginPath();
                    this.ctx.moveTo(this.cx + p0.x, this.cy + p0.y);
                    this.ctx.lineTo(this.cx + p1.x, this.cy + p1.y);
                    this.ctx.lineTo(this.cx + p2.x, this.cy + p2.y);
                    this.ctx.closePath();
                    this.ctx.fill();
                });

                // Draw coin rim outline
                this.ctx.strokeStyle = 'rgba(180, 150, 100, 0.4)';
                this.ctx.lineWidth = 1.5;
                this.ctx.beginPath();
                for (let j = 0; j <= 60; j++) {
                    const a = (j / 60) * Math.PI * 2;
                    const v = new Vec3(Math.cos(a)*100, Math.sin(a)*100, 0)
                        .rotateX(flipAngle).rotateY(spinAngle);
                    const p = v.project(600);
                    if (j === 0) this.ctx.moveTo(this.cx + p.x, this.cy + p.y);
                    else this.ctx.lineTo(this.cx + p.x, this.cy + p.y);
                }
                this.ctx.closePath();
                this.ctx.stroke();

                // Text overlay based on facing direction
                const isFront = Math.cos(flipAngle) > 0;

                this.ctx.font = 'bold 42px Arial';
                this.ctx.fillStyle = 'rgba(255, 255, 255, 0.18)';
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';

                if (isFront) {
                    this.ctx.fillText('WT', this.cx, this.cy - 18);
                    this.ctx.font = 'bold 16px Arial';
                    this.ctx.fillText('MINT', this.cx, this.cy + 28);
                } else {
                    this.ctx.font = 'bold 28px Arial';
                    this.ctx.fillText('10,000', this.cx, this.cy - 12);
                    this.ctx.font = 'bold 22px Arial';
                    this.ctx.fillText('TOKENS', this.cx, this.cy + 22);
                }

                // Moving specular highlight
                const hlX = Math.cos(spinAngle - Math.PI/4) * 65;
                const hlY = Math.sin(flipAngle) * 30 - 65;

                const hlGrad = this.ctx.createRadialGradient(this.cx+hlX, this.cy+hlY, 0, 
                    this.cx+hlX, this.cy+hlY, 75);
                hlGrad.addColorStop(0, 'rgba(255, 255, 255, 0.6)');
                hlGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.1)');
                hlGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');

                this.ctx.fillStyle = hlGrad;
                this.ctx.beginPath();
                this.ctx.arc(this.cx + hlX, this.cy + hlY, 75, 0, Math.PI*2);
                this.ctx.fill();
            }
        }

        // Initialize hero coin
        const heroCanvas = document.getElementById('coin-hero');
        heroCanvas.width = 400;
        heroCanvas.height = 400;

        const renderer = new CoinRenderer(heroCanvas);
        let animId = null, startTime = Date.now();

        function animate() {
            if (renderer.animating) {
                const t = ((Date.now() - startTime) / 1000 / 4) % 1;
                renderer.render(t);
                animId = requestAnimationFrame(animate);
            }
        }
        animate();

        // Edition coins
        function renderEditionCoin(canvas, edition) {
            const ctx = canvas.getContext('2d');
            const w = canvas.width, h = canvas.height;
            const cx = w/2, cy = h/2, r = Math.min(w,h)*0.35;

            ctx.fillStyle = '#0a0f1f';
            ctx.fillRect(0, 0, w, h);

            const colors = {
                bronze: {main:'#b87333', light:'#cd7f32', dark:'#704214'},
                silver: {main:'#c0c0c0', light:'#e8e8e8', dark:'#808080'},
                gold: {main:'#d4af37', light:'#ffd700', dark:'#b8960d'},
                black: {main:'#2a2a2a', light:'#555555', dark:'#0a0a0a'}
            };

            const c = colors[edition];
            const grad = ctx.createRadialGradient(cx-20, cy-20, 0, cx, cy, r);
            grad.addColorStop(0, c.light);
            grad.addColorStop(0.5, c.main);
            grad.addColorStop(1, c.dark);

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI*2);
            ctx.fill();

            ctx.strokeStyle = c.dark;
            ctx.lineWidth = 2;
            ctx.stroke();

            ctx.font = 'bold 20px Arial';
            ctx.fillStyle = 'rgba(255,255,255,0.3)';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('WT', cx, cy);

            const hlGrad = ctx.createRadialGradient(cx-18, cy-18, 0, cx-18, cy-18, 45);
            hlGrad.addColorStop(0, 'rgba(255,255,255,0.7)');
            hlGrad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = hlGrad;
            ctx.beginPath();
            ctx.arc(cx-18, cy-18, 45, 0, Math.PI*2);
            ctx.fill();
        }

        document.querySelectorAll('.edition-canvas').forEach((c, i) => {
            c.width = c.parentElement.offsetWidth;
            c.height = 200;
            renderEditionCoin(c, ['bronze','silver','gold','black'][i]);
        });

        // API for grading
        window.demo = {
            canvas: heroCanvas,
            setTime(t) { renderer.render(t); },
            pause() {
                renderer.animating = false;
                if (animId) cancelAnimationFrame(animId);
            }
        };
    </script>
</body>
</html>
